-- =====================================================================
-- FixMyRide - am_user schema and seed data
-- Target database : am_user   (PostgreSQL 18, server "automate")
-- Generated from  : docs/FixMyRide-SRS-HLD-LLD.pdf, section 7.2 (Data design)
--
-- Schema is a faithful port of the LLD tables. SQLite -> PostgreSQL mapping:
--   INTEGER PK AUTOINCREMENT -> INTEGER GENERATED BY DEFAULT AS IDENTITY
--   TEXT                     -> TEXT
--   REAL (money)             -> NUMERIC(10,2)      REAL (rating) -> NUMERIC(2,1)
--   TEXT DEFAULT datetime()  -> TIMESTAMPTZ DEFAULT now()
--   INTEGER 0/1 flags        -> INTEGER (kept as in the LLD, not BOOLEAN)
-- Cross-module columns (mechanic_id in user db, service_request_id in mechanic
-- db, every mirror table in admin db) carry NO foreign key, exactly as the LLD
-- specifies - the three databases stay independently deployable.
--
-- IDs are aligned across all three databases: user #7 is user #7 everywhere,
-- mechanic #12 is mechanic #12 everywhere, and service request #5 is job #5
-- and service_overview #5. This makes the mirrors joinable by hand.
--
-- Contains: users, vehicles, service_requests, payments, issues, notifications, mechanics, reviews
-- Each table is seeded with 30 rows. Password for every seeded principal is
-- "password123" (stored as a real bcrypt hash).
--
-- Run with:
--   psql -U postgres -h localhost -d am_user -f <this file>
-- The script is idempotent: it drops and recreates its own tables.
-- =====================================================================

BEGIN;


-- ---------------------------------------------------------------------
-- 1. SCHEMA
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS reviews, issues, payments, service_requests,
                     vehicles, notifications, mechanics, users CASCADE;

CREATE TABLE users (
    id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name            TEXT        NOT NULL,
    email           TEXT        NOT NULL UNIQUE,
    password_hash   TEXT        NOT NULL,
    phone           TEXT,
    address         TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE vehicles (
    id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id         INTEGER     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    make            TEXT        NOT NULL,
    model           TEXT        NOT NULL,
    year            INTEGER     NOT NULL,
    registration_no TEXT        NOT NULL UNIQUE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE service_requests (
    id                 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id            INTEGER     NOT NULL REFERENCES users(id)    ON DELETE CASCADE,
    vehicle_id         INTEGER     NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE,
    mechanic_id        INTEGER,                     -- cross-module, no FK by design
    category           TEXT        NOT NULL,
    description        TEXT        NOT NULL,
    status             TEXT        NOT NULL DEFAULT 'pending'
                       CHECK (status IN ('pending','assigned','accepted',
                                         'in_progress','completed','cancelled')),
    scheduled_at       TIMESTAMPTZ,
    price              NUMERIC(10,2),
    booking_ref        TEXT,
    estimated_duration TEXT,
    rated              INTEGER     NOT NULL DEFAULT 0,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE payments (
    id                 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    service_request_id INTEGER     NOT NULL REFERENCES service_requests(id) ON DELETE CASCADE,
    user_id            INTEGER     NOT NULL REFERENCES users(id)            ON DELETE CASCADE,
    amount             NUMERIC(10,2) NOT NULL,
    method             TEXT        NOT NULL,
    status             TEXT        NOT NULL DEFAULT 'pending'
                       CHECK (status IN ('pending','paid','failed','refunded')),
    transaction_ref    TEXT        NOT NULL,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE issues (
    id                 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id            INTEGER     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    service_request_id INTEGER     REFERENCES service_requests(id) ON DELETE SET NULL,
    title              TEXT        NOT NULL,
    description        TEXT        NOT NULL,
    image_path         TEXT,
    status             TEXT        NOT NULL DEFAULT 'open'
                       CHECK (status IN ('open','investigating','resolved','closed')),
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE notifications (
    id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    recipient_role TEXT        NOT NULL,
    recipient_id   INTEGER     NOT NULL,
    title          TEXT        NOT NULL,
    body           TEXT        NOT NULL,
    read           INTEGER     NOT NULL DEFAULT 0,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Discovery mirror. id is a plain INTEGER PK (no identity) because the values
-- are assigned by the mechanic module, not generated here.
CREATE TABLE mechanics (
    id              INTEGER PRIMARY KEY,
    name            TEXT,
    specialization  TEXT,
    skills          TEXT,
    workshop_name   TEXT,
    location        TEXT,
    price_from      NUMERIC(10,2),
    rating          NUMERIC(2,1),
    reviews_count   INTEGER     DEFAULT 0,
    available       INTEGER     DEFAULT 1,
    approval_status TEXT        DEFAULT 'approved',
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE reviews (
    id                 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    service_request_id INTEGER     NOT NULL REFERENCES service_requests(id) ON DELETE CASCADE,
    mechanic_id        INTEGER,
    user_id            INTEGER     NOT NULL,
    user_name          TEXT,
    rating             INTEGER     NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comment            TEXT,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Indexes (LLD section 7.2.4)
CREATE INDEX idx_vehicles_user     ON vehicles(user_id);
CREATE INDEX idx_services_user     ON service_requests(user_id);
CREATE INDEX idx_payments_user     ON payments(user_id);
CREATE INDEX idx_issues_user       ON issues(user_id);
CREATE INDEX idx_reviews_mechanic  ON reviews(mechanic_id);


-- ---------------------------------------------------------------------
-- 2. SEED DATA (30 rows per table)
-- ---------------------------------------------------------------------

