-- issues ----------------------------------------------------------
INSERT INTO issues (id, user_id, service_request_id, title, description,
                    image_path, status, created_at) VALUES
  (1, 1, 1, 'Invoice amount higher than the quote', 'The final invoice is 1,200 more than the estimate shared at booking.', '/uploads/issues/issue_001.jpg', 'resolved', '2026-01-11 18:23:00+05:30'),
  (2, 2, 2, 'Mechanic arrived late', 'Scheduled slot was 10:00 but work started only at 12:30.', '/uploads/issues/issue_002.jpg', 'closed', '2026-01-18 18:46:00+05:30'),
  (3, 3, 3, 'Noise returned after service', 'The rattling sound came back three days after the repair.', NULL, 'investigating', '2026-01-25 18:09:00+05:30'),
  (4, 4, 4, 'Wrong part fitted', 'An aftermarket filter was used instead of the OEM part I paid for.', '/uploads/issues/issue_004.jpg', 'resolved', '2026-02-01 18:32:00+05:30'),
  (5, 5, 5, 'Car returned unwashed', 'Complimentary wash mentioned in the package was not done.', '/uploads/issues/issue_005.jpg', 'closed', '2026-02-08 18:55:00+05:30'),
  (6, 6, 6, 'Payment deducted twice', 'UPI was debited twice for the same booking reference.', NULL, 'resolved', '2026-02-15 18:18:00+05:30'),
  (7, 7, 7, 'Scratch on the bonnet', 'A fresh scratch appeared on the bonnet after the workshop visit.', '/uploads/issues/issue_007.jpg', 'investigating', '2026-02-22 18:41:00+05:30'),
  (8, 8, 8, 'AC still not cooling', 'Cooling dropped again within a week of the gas refill.', '/uploads/issues/issue_008.jpg', 'open', '2026-03-01 18:04:00+05:30'),
  (9, 9, 9, 'Delay in delivery', 'Car was promised by Friday evening but delivered on Sunday.', NULL, 'closed', '2026-03-08 18:27:00+05:30'),
  (10, 10, 10, 'Missing floor mat', 'One of the rear floor mats was not returned with the car.', '/uploads/issues/issue_010.jpg', 'resolved', '2026-03-15 18:50:00+05:30'),
  (11, 11, 11, 'Brake noise persists', 'Squealing continues at low speed after the brake job.', '/uploads/issues/issue_011.jpg', 'investigating', '2026-03-22 18:13:00+05:30'),
  (12, 12, 12, 'Estimate not shared', 'Work was started before any written estimate was sent.', NULL, 'closed', '2026-03-29 18:36:00+05:30'),
  (13, 13, 13, 'Battery warranty query', 'Need the warranty card for the battery replaced last month.', '/uploads/issues/issue_013.jpg', 'resolved', '2026-04-05 18:59:00+05:30'),
  (14, 14, 14, 'Rude behaviour at pickup', 'The pickup executive was uncooperative about the delay.', '/uploads/issues/issue_014.jpg', 'closed', '2026-04-12 18:22:00+05:30'),
  (15, 15, 15, 'Oil leak after service', 'A small oil patch appears under the car overnight.', NULL, 'investigating', '2026-04-19 18:45:00+05:30'),
  (16, 16, 16, 'App status not updating', 'Tracking showed in progress even after delivery.', '/uploads/issues/issue_016.jpg', 'resolved', '2026-04-26 18:08:00+05:30'),
  (17, 17, 17, 'Refund not received', 'Refund for the cancelled booking has not been credited.', '/uploads/issues/issue_017.jpg', 'open', '2026-05-03 18:31:00+05:30'),
  (18, 18, 18, 'Alignment still off', 'Steering continues to pull left after the alignment.', NULL, 'investigating', '2026-05-10 18:54:00+05:30'),
  (19, 19, 19, 'Extra labour charge', 'A labour line item was added that was never discussed.', '/uploads/issues/issue_019.jpg', 'resolved', '2026-05-17 18:17:00+05:30'),
  (20, 20, 20, 'Paint shade mismatch', 'The repainted door is a slightly different shade.', '/uploads/issues/issue_020.jpg', 'open', '2026-05-24 18:40:00+05:30'),
  (21, 21, 21, 'Wrong tyre size fitted', 'Fitted tyres are one size narrower than requested.', NULL, 'resolved', '2026-05-31 18:03:00+05:30'),
  (22, 22, 22, 'Service reminder not received', 'No reminder came for the scheduled periodic service.', '/uploads/issues/issue_022.jpg', 'closed', '2026-06-07 18:26:00+05:30'),
  (23, 23, 23, 'Gearbox noise after repair', 'A whining sound appears in second gear after the repair.', '/uploads/issues/issue_023.jpg', 'investigating', '2026-06-14 18:49:00+05:30'),
  (24, 24, 24, 'Interior left dirty', 'Grease marks on the steering wheel and gear knob.', NULL, 'closed', '2026-06-21 18:12:00+05:30'),
  (25, 25, 25, 'Warning light back on', 'The engine check light reappeared after two days.', '/uploads/issues/issue_025.jpg', 'open', '2026-06-28 18:35:00+05:30'),
  (26, 26, 26, 'Duplicate booking created', 'The app created two bookings for the same slot.', '/uploads/issues/issue_026.jpg', 'resolved', '2026-07-05 18:58:00+05:30'),
  (27, 27, 27, 'Spare wheel missing', 'Spare wheel was not put back in the boot after service.', NULL, 'resolved', '2026-07-12 18:21:00+05:30'),
  (28, 28, 28, 'Fuel level dropped', 'Fuel gauge reads noticeably lower than at handover.', '/uploads/issues/issue_028.jpg', 'investigating', '2026-07-19 18:44:00+05:30'),
  (29, 29, 29, 'Invoice not emailed', 'Tax invoice was never delivered to my registered email.', '/uploads/issues/issue_029.jpg', 'closed', '2026-07-26 18:07:00+05:30'),
  (30, 30, 30, 'Follow-up check refused', 'Workshop declined a free re-check within the warranty period.', NULL, 'open', '2026-08-02 18:30:00+05:30');


